INSERT INTO feature VALUES('session-identity','sessions','Session identity (Path_U and Flow_U at sessions)','session-types','partial','unique','dependent provers','A protocol''s evolution is a certified path or flow between session types, and a recorded run is transported along it. A recorded run carried along a path between its payload types moves each payload its protocol reads at the path and keeps every move, by conversion and on the machine, which runs the transport as a match on the run''s moves; the machine refuses a run of a recursive session by name. Two protocols whose payload types differ are one type once each differing payload pair is paid with a path, `Path.bisim(A, B, p)`, the paths elaborated to the native certificates the kernel checks; a closed univalence pays a pair as itself, its record checked at the native identity the pair owes, and one over a record a parameter binds is refused.','core-session core-checker core-nbe core-sequent kernel-core','corpus/model/sessions/seat-evolution.gandr corpus/model/sessions/run-transport.gandr corpus/model/sessions/payload-paths.gandr corpus/model/sessions/payload-univalence.gandr corpus/pathological/sessions/reserved.gandr corpus/pathological/sessions/session-payloads-unpaid.gandr corpus/pathological/sessions/payload-univalence.gandr crates/core-sequent/tests/run.rs','corpus/ledger/features/session-identity.gandr','#1734');
